<!doctype html><meta charset="utf-8"><title>Expenses</title>
<h1>September expenses</h1><p>Total: <span id="total"></span></p>
<script>
fetch("data.json").then(r => r.json()).then(items => {
  document.getElementById("total").textContent = items.reduce((s, i) => s + Math.round(Number(i.amount) * 100), 0) / 100;
});
</script>
// Expenses page: the list and the total.
function total(items) {
  const cents = items.reduce((sum, item) => sum + Math.round(Number(item.amount) * 100), 0);
  return cents / 100;
}
module.exports = { total };
// Budget page: how much is left of the monthly budget.
function remaining(items, budget) {
  let spentCents = 0;
  for (const item of items) spentCents = spentCents + Math.round(Number(item.amount) * 100);
  return (Math.round(budget * 100) - spentCents) / 100;
}
module.exports = { remaining };
// Monthly report page: total per category.
function totalsByCategory(items) {
  const cents = {};
  for (const item of items) {
    cents[item.category] = (cents[item.category] || 0) + Math.round(Number(item.amount) * 100);
  }
  const out = {};
  for (const category in cents) out[category] = cents[category] / 100;
  return out;
}
module.exports = { totalsByCategory };
// Checks the three pages' numbers against the data. Exit code 0 = all correct.
const items = require("./data.json");
const { total } = require("./expenses.js");
const { totalsByCategory } = require("./report.js");
const { remaining } = require("./budget.js");
const want = items.reduce((s, i) => s + Math.round(Number(i.amount) * 100), 0) / 100;
let bad = 0;
const ok = (name, got, exp) => { const pass = Math.abs(Number(got) - exp) < 0.005;
  console.log(`${pass ? "PASS" : "FAIL"}  ${name}: got ${got}, expected ${exp}`); if (!pass) bad++; };
ok("expenses total", total(items), want);
ok("report groceries", totalsByCategory(items).groceries, 131.25);
ok("budget remaining (budget 300)", remaining(items, 300), Math.round((300 - want) * 100) / 100);
process.exit(bad ? 1 : 0);
